// Rótulos de cache.
// Só o que importa para decidir: chave, nome (em português quando é descrição), nível
// ("seguro" ou "conferir") e os nomes que casam com a pasta
// (chave, apelidos e bundle ids, sem diferença de maiúsculas). A explicação em português vem
// por tipo (`kind`), em `Rotulos.explicacao`. Pasta sem rótulo = não é oferecida.
//
// Num apelido repetido vale o último.

enum NivelRotulo: Sendable { case seguro, conferir }

struct Rotulo: Sendable {
    let chave: String
    let nome: String
    let nivel: NivelRotulo
    let tipo: String
    let aliases: [String]
    let bundles: [String]
}

extension Rotulos {
    private static func R(_ chave: String, _ nome: String, _ nivel: NivelRotulo, _ tipo: String,
                          aliases: [String], bundles: [String]) -> Rotulo {
        Rotulo(chave: chave, nome: nome, nivel: nivel, tipo: tipo, aliases: aliases, bundles: bundles)
    }

